/* Punjab Dairy: offline-first, no server. All records stored in IndexedDB on this device. */
const $=s=>document.querySelector(s), app=$('#app'), today=()=>new Date().toLocaleDateString('en-CA'), money=n=>'Rs '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:2}), n=v=>Number(v)||0, uid=()=>crypto.randomUUID(), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db, data, session=null, view='dashboard', editor=null, activeInvoice=null, flash='';
let navHistory=[], entryTab='delivery', selectedProfitMonth=today().slice(0,7), currentCalendarMonth=today().slice(0,7);
const blank=()=>({version:1,created:today(),users:[],customers:[],suppliers:[],staff:[],expenses:[],entries:[],payments:[],feedback:[],remainders:[],settings:{shop:'Punjab Dairy'}});
function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('punjab-dairy-data',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function readDB(){return new Promise((resolve,reject)=>{let t=db.transaction('state','readonly').objectStore('state').get('all');t.onsuccess=()=>resolve(t.result);t.onerror=()=>reject(t.error)})}
function saveDB(){return new Promise((resolve,reject)=>{let t=db.transaction('state','readwrite');t.objectStore('state').put(data,'all');t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
async function hash(p,salt){let b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+':'+p));return Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join('')}
async function credentials(phone,pw,role,customerId){let salt=uid();return {id:uid(),phone:String(phone).trim(),salt,hash:await hash(pw,salt),role,customerId:customerId||null}}
const timestamp=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')+'T'+[String(d.getHours()).padStart(2,'0'),String(d.getMinutes()).padStart(2,'0')].join(':')};
const dateOnly=x=>String(x||'').slice(0,10);
const list=k=>data[k]||[], find=(k,id)=>list(k).find(x=>x.id===id), qty=e=>n(e.cowQty)+n(e.buffaloQty)+n(e.yogurtQty), amt=e=>e.type==='shop'&&e.shopAmount!=null?n(e.shopAmount):n(e.cowQty)*n(e.cowRate)+n(e.buffaloQty)*n(e.buffaloRate)+n(e.yogurtQty)*n(e.yogurtRate);
const sales=()=>list('entries').filter(e=>e.type==='shop'||e.type==='delivery'), purchases=()=>list('entries').filter(e=>e.type==='purchase');
const invoiceLogo='data:image/png;base64,';
const activeParty=p=>p?.active!==false && p?.isActive!==false;
const iconAction=(symbol,title,key,id='',cls='')=>`<button type="button" class="icon-action ${cls}" data-action="${key}" data-id="${esc(id)}" title="${esc(title)}" aria-label="${esc(title)}">${symbol}</button>`;
const editActions=(kind,id)=>`<div class="icon-actions">${iconAction('✎','Edit '+kind,'edit-'+kind,id)}${iconAction('🗑','Delete '+kind,'delete-'+kind,id,'danger')}</div>`;
const pageState={}; const pageSize=12;
function paginate(key,items,headers,rowRenderer){const count=items.length,max=Math.max(1,Math.ceil(count/pageSize));pageState[key]=Math.min(max,Math.max(1,pageState[key]||1));let page=pageState[key],subset=items.slice((page-1)*pageSize,page*pageSize);return `${table(headers,subset.map(rowRenderer))}<div class="pager"><span>${count?((page-1)*pageSize+1):0}–${Math.min(page*pageSize,count)} of ${count}</span><div class="icon-actions">${iconAction('‹','Previous page','page-prev',key)}<b>${page} / ${max}</b>${iconAction('›','Next page','page-next',key)}</div></div>`}
function setPage(key,offset){pageState[key]=Math.max(1,(pageState[key]||1)+offset);render()}
const total=a=>a.reduce((s,x)=>s+amt(x),0), totalPayments=(kind,id)=>list('payments').filter(p=>p.partyType===kind&&p.partyId===id).reduce((s,p)=>s+n(p.amount),0);
const customerBalance=id=>total(list('entries').filter(e=>e.type==='delivery'&&e.partyId===id))-totalPayments('customer',id);
const supplierBalance=id=>total(list('entries').filter(e=>e.type==='purchase'&&e.partyId===id))-totalPayments('supplier',id);
const within=(d,a,b)=>dateOnly(d)>=a&&dateOnly(d)<=b;
function dates(period,anchor=today()){let d=new Date(anchor+'T12:00:00'), first=new Date(d);if(period==='day'){}else if(period==='week'){first.setDate(d.getDate()-(d.getDay()+6)%7)}else if(period==='month'){first.setDate(1)}else if(period==='quarter'){first.setMonth(Math.floor(d.getMonth()/3)*3,1)}else if(period==='year'){first.setMonth(0,1)}let format=x=>[x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-');return [format(first),format(d)]}
function stats(period='day',anchor=today()){let[a,b]=dates(period,anchor), e=list('entries').filter(x=>within(x.date,a,b)),costs=list('expenses').filter(x=>within(x.date,a,b)),shop=e.filter(x=>x.type==='shop'),delivery=e.filter(x=>x.type==='delivery'),buy=e.filter(x=>x.type==='purchase');let staffCost=list('staff').filter(x=>x.active!==false).reduce((s,x)=>s+n(x.salary),0)*({day:1/30,week:7/30,month:1,quarter:3,year:12}[period]);let revenue=total([...shop,...delivery]),purchase=total(buy),expense=costs.reduce((s,x)=>s+n(x.amount),0);return {shop:total(shop),delivery:total(delivery),purchase,revenue,expense,staffCost,profit:revenue-purchase-expense-staffCost,shopQty:shop.reduce((s,x)=>s+qty(x),0),deliveryQty:delivery.reduce((s,x)=>s+qty(x),0),purchaseQty:buy.reduce((s,x)=>s+qty(x),0)}}
const button=(label,act='')=>`<button class="btn ${act==='cancel'?'secondary':''}" type="button" data-action="${esc(act)}">${label}</button>`;
function layout(body){let isAdmin=session?.role==='admin', tabs=isAdmin?[['dashboard','Home'],['entries','Entries'],['customers','Customers'],['suppliers','Suppliers'],['payments','Payments'],['invoices','Bills'],['more','More']]:[['dashboard','Home'],['invoices','My Bills'],['profile','Profile'],['feedback','Feedback']];app.innerHTML=`<div class="shell"><header class="top"><div class="brand"><div class="logo"><img src="logo.png" alt="Punjab Dairy logo"></div><div><h1>Punjab Dairy</h1><p>Fresh milk • Smart management • Offline</p></div></div><button class="btn secondary sm" data-action="logout">Log out</button></header><nav class="nav">${tabs.map(([k,v])=>`<button data-view="${k}" class="${view===k?'active':''}">${v}</button>`).join('')}</nav><main class="main">${(editor||view!=='dashboard')?`<button class="back-control" type="button" data-action="go-back" aria-label="Go back">‹ Back</button>`:''}${flash?`<div class="alert success">${esc(flash)}</div>`:''}${body}</main><div class="footer">Offline records • Back up regularly</div></div>`;flash=''}
function title(t,sub='',extra=''){return `<div class="heading"><div><h2>${t}</h2>${sub?`<span class="muted">${sub}</span>`:''}</div>${extra}</div>`}
const stat=(label,value,hint='')=>`<div class="stat"><small>${label}</small><strong>${value}</strong><em>${hint}</em></div>`;
const action=(label,a,id='',cls='secondary')=>`<button class="btn ${cls} sm" data-action="${a}" data-id="${esc(id)}">${label}</button>`;
const th=labels=>`<thead><tr>${labels.map(x=>`<th>${x}</th>`).join('')}</tr></thead>`;
const table=(headers,rows)=>`<div class="tablewrap"><table class="table">${th(headers)}<tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">No records yet</td></tr>`}</tbody></table></div>`;
const input=(name,label,value='',type='text',extra='')=>`<label class="field">${label}<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,opts,value)=>`<label class="field">${label}<select id="${name}" name="${name}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const area=(name,label,value='')=>`<label class="field full">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
function auth(){
 let saved=localStorage.getItem('pd-remember-username')||'';
 app.innerHTML=`<div class="auth"><div class="auth-card"><div class="logo"><img src="logo.png" alt="Punjab Dairy logo"></div><h1>Punjab Dairy</h1><p>Sign in to manage your dairy</p>${flash?`<div class="alert">${esc(flash)}</div>`:''}<form data-form="login">${input('phone','Username or mobile number',saved,'text','required autocomplete="username"')}${input('password','Password','','password','required minlength="6" autocomplete="current-password"')}<button class="btn primary-wide" type="submit">Sign in</button></form></div></div>`;flash=''
}
function customerMonthSummary(c,month){let [yy,mm]=month.split('-').map(Number);let start=`${yy}-${String(mm).padStart(2,'0')}-01`;let end=`${yy}-${String(mm).padStart(2,'0')}-${String(new Date(yy,mm,0).getDate()).padStart(2,'0')}`;let es=list('entries').filter(e=>e.type==='delivery'&&e.partyId===c?.id&&within(e.date,start,end));let ps=list('payments').filter(e=>e.partyType==='customer'&&e.partyId===c?.id&&within(e.date,start,end));return {start,end,es,ps,bill:total(es),paid:ps.reduce((a,p)=>a+n(p.amount),0)} }
function dashboard(){
 if(session.role==='customer'){let c=find('customers',session.customerId),m=selectedCustomerMonth,z=customerMonthSummary(c,m);return layout(`${title('Welcome, '+esc(c?.name||'Customer'),'Your milk account')}<div class="stats">${stat('This month bill',money(z.bill))}${stat('Paid this month',money(z.paid))}${stat('Total account balance',money(customerBalance(c?.id)))}${stat('Milk this month',z.es.reduce((a,e)=>a+n(e.cowQty)+n(e.buffaloQty),0).toFixed(2)+' L')}</div><div class="panel"><h3>Check previous months</h3><div class="toolrow"><label>Month <input type="month" id="customermonth" value="${m}"></label></div><div id="customermonthresult"></div></div>`),updateCustomerMonth()}
 layout(`${title('Business dashboard','Punjab Dairy • '+today(),'<div class="filters"><select id="period"><option value="day">Today</option><option value="week">This week</option><option value="month">This month</option><option value="quarter">Quarter</option><option value="year">Year</option></select><input id="reportdate" type="date" value="'+today()+'"></div>')}<div id="report"></div><div class="panel"><h3>Quick daily work</h3><div class="quick">${action('⚡ Bulk deliveries','bulk')}${action('🏠 Home delivery','quick-delivery')}${action('🚚 Purchase','quick-purchase')}${action('🏪 Shop sale','quick-shop')}${action('🧾 Remaining stock','go-remainder')}</div></div><div class="grid2"><div class="panel"><div class="section-title"><h3>Supplier dues</h3>${action('View all suppliers','go-suppliers')}</div><div id="supplieroverview"></div></div><div class="panel"><div class="section-title"><h3>Customer balances</h3>${action('View all customers','go-customers')}</div><div class="duelist">${list('customers').filter(c=>customerBalance(c.id)>0).sort((a,b)=>customerBalance(b.id)-customerBalance(a.id)).slice(0,5).map(c=>`<div><span>${esc(c.name)}</span><b>${money(customerBalance(c.id))}</b></div>`).join('')||'<p class="muted">No unpaid customer balances</p>'}</div></div></div>`);updateReport()
}
let selectedCustomerMonth=today().slice(0,7);function updateCustomerMonth(){let c=find('customers',session.customerId),m=$('#customermonth')?.value||selectedCustomerMonth;selectedCustomerMonth=m,z=customerMonthSummary(c,m),el=$('#customermonthresult');if(!el)return;el.innerHTML=`<div class="stats mini-stats">${stat('Billed',money(z.bill))}${stat('Paid',money(z.paid))}${stat('Month balance',money(z.bill-z.paid))}</div>${paginate('customer-month',z.es.slice().sort((a,b)=>b.date.localeCompare(a.date)),['Date','Cow L','Buffalo L','Yogurt kg','Amount'],e=>`<tr><td>${esc(e.date)}</td><td>${n(e.cowQty)}</td><td>${n(e.buffaloQty)}</td><td>${n(e.yogurtQty)}</td><td>${money(amt(e))}</td></tr>`) }<p class="note">This month balance is billed minus payments in the chosen month. Account balance includes prior periods.</p>`}
function updateReport(){let period=$('#period')?.value||'day',d=$('#reportdate')?.value||today(),s=stats(period,d),el=$('#report');if(!el)return;let outstanding=list('suppliers').reduce((a,x)=>a+supplierBalance(x.id),0),receivable=list('customers').reduce((a,x)=>a+customerBalance(x.id),0);el.innerHTML=`<div class="stats"><div class="stat feature-stat"><small>Total sales • Shop + Home</small><strong>${money(s.revenue)}</strong><em>Combined sales for selected period</em></div>${stat('Shop sales',money(s.shop),s.shopQty.toFixed(2)+' L/kg')}${stat('Home deliveries',money(s.delivery),s.deliveryQty.toFixed(2)+' L/kg')}${stat('Milk purchased',money(s.purchase),s.purchaseQty.toFixed(2)+' L/kg')}${stat('Estimated net',money(s.profit),s.profit<0?'Loss':'Profit after expenses/salaries')}${stat('Supplier dues • All time',money(outstanding))}${stat('Customer receivables',money(receivable))}${stat('Operating expenses',money(s.expense+s.staffCost),'Including allocated salaries')}${(()=>{let r=list('remainders').find(x=>x.date===d);return stat('Remaining stock • '+d,r?((n(r.cowQty)+n(r.buffaloQty)).toFixed(2)+' L milk'):'Not entered',r?n(r.yogurtQty).toFixed(2)+' kg yogurt':'Use More → Remaining milk & yogurt')})()}</div>`;el.insertAdjacentHTML('beforeend',monthlyProfitPanel());let o=$('#supplieroverview');if(o)o.innerHTML=`<div class="duelist">${list('suppliers').filter(p=>supplierBalance(p.id)>0).sort((a,b)=>supplierBalance(b.id)-supplierBalance(a.id)).slice(0,4).map(p=>`<div><span>${esc(p.name)}</span><b>${money(supplierBalance(p.id))}</b></div>`).join('')||'<p class="muted">No outstanding supplier balance</p>'}</div>`}

function grossForDate(date){let e=list('entries').filter(x=>dateOnly(x.date)===date);return total(e.filter(x=>x.type==='shop'||x.type==='delivery'))-total(e.filter(x=>x.type==='purchase'))}
function monthAccounting(month){
 const [year,m]=month.split('-').map(Number),last=new Date(year,m,0).getDate();
 const days=Array.from({length:last},(_,i)=>month+'-'+String(i+1).padStart(2,'0'));
 const points=days.map(date=>({date,gross:grossForDate(date)}));
 const gross=points.reduce((v,p)=>v+p.gross,0);
 const exp=list('expenses').filter(e=>dateOnly(e.date).startsWith(month));
 const recordedExpenses=exp.reduce((v,e)=>v+n(e.amount),0);
 // A salary entered as an expense is already counted: do not count it twice.
 const alreadyPaidSalary=exp.filter(x=>/salary|salaries|تنخواہ/i.test(String(x.category||''))).reduce((v,e)=>v+n(e.amount),0);
 const budgetedSalary=list('staff').filter(s=>s.active!==false).reduce((v,s)=>v+n(s.salary),0);
 const salary=Math.max(budgetedSalary,alreadyPaidSalary);
 return {month,points,gross,expenses:recordedExpenses,salary,net:gross-recordedExpenses-Math.max(0,salary-alreadyPaidSalary),budgetedSalary,alreadyPaidSalary};
}
function monthlyProfitPanel(){
 let a=monthAccounting(selectedProfitMonth),vals=a.points.map(p=>p.gross),min=Math.min(0,...vals),max=Math.max(0,...vals),span=Math.max(1,max-min);
 const w=960,h=270,pl=65,pr=25,pt=30,pb=42,plotW=w-pl-pr,plotH=h-pt-pb;
 const xp=i=>pl+i*plotW/Math.max(1,vals.length-1),yp=v=>pt+(max-v)/span*plotH;
 const path=vals.map((v,i)=>(i?'L':'M')+xp(i).toFixed(1)+' '+yp(v).toFixed(1)).join(' ');
 const zero=yp(0);
 const ticks=[0,Math.floor((vals.length-1)/4),Math.floor((vals.length-1)/2),Math.floor(3*(vals.length-1)/4),vals.length-1].filter((v,i,ar)=>ar.indexOf(v)===i);
 return `<div class="panel monthly-report"><div class="section-title"><div><h3>📈 Daily gross profit — ${esc(selectedProfitMonth)}</h3><p class="muted">Home delivery + shop sale − supplier purchase</p></div><label class="month-filter">Month <input id="profitmonth" type="month" value="${esc(selectedProfitMonth)}"></label></div><div class="stats mini-stats"><div class="stat"><small>Monthly gross profit</small><strong>${money(a.gross)}</strong></div><div class="stat"><small>Estimated net profit</small><strong>${money(a.net)}</strong></div></div><div class="profit-chart" role="img" aria-label="Daily gross profit for ${esc(selectedProfitMonth)}"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><line x1="${pl}" y1="${zero}" x2="${w-pr}" y2="${zero}" stroke="#a5b8a9" stroke-width="2"/><path d="${path}" fill="none" stroke="#126b39" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${xp(i)}" cy="${yp(v)}" r="5" fill="${v<0?'#ba313a':'#126b39'}" />`).join('')}${ticks.map(i=>`<text x="${xp(i)}" y="${h-9}" text-anchor="middle" font-size="14" fill="#47634f">${i+1}</text>`).join('')}</svg><div class="profit-touch">${a.points.map((p,i)=>`<button class="profit-point" type="button" data-action="profit-point" data-id="${esc(p.date)}" style="left:${xp(i)/w*100}%;top:0;height:100%;" aria-label="${esc(p.date)}: ${money(p.gross)}" title="${esc(p.date)}: ${money(p.gross)}"></button>`).join('')}</div></div><p class="profit-tip" id="profitdetail">Touch a day to see its profit. A new month starts a fresh chart automatically; records are never deleted.</p><div class="accounting-grid"><div><span>Sales minus purchases</span><b>${money(a.gross)}</b></div><div><span>Recorded expenses (including rent)</span><b>− ${money(a.expenses)}</b></div><div><span>Additional salary allocation</span><b>− ${money(Math.max(0,a.salary-a.alreadyPaidSalary))}</b></div><div class="accounting-final"><span>Estimated month net</span><b>${money(a.net)}</b></div></div><p class="note">Recorded salary expenses are not counted a second time. The estimate uses purchase costs, not unsold closing stock valuation. If rent is not recorded under Expenses, add it to obtain an accurate net estimate.</p></div>`;
}
function dashboardChart(period,anchor){return monthlyProfitPanel()}

const defaults={customer:{name:'',phone:'',address:'',registered:today(),cowRate:0,buffaloRate:0,yogurtRate:0,cowQty:0,buffaloQty:0,yogurtQty:0,username:'',active:true},supplier:{name:'',phone:'',address:'',registered:today(),cowRate:0,buffaloRate:0,paymentCycle:7,active:true},staff:{name:'',phone:'',role:'',salary:0,registered:today(),active:true},expense:{date:today(),category:'General',description:'',amount:0}};
function entityForm(kind,id){let plural={customer:'customers',supplier:'suppliers',staff:'staff',expense:'expenses'}[kind],old=id?find(plural,id):null,x={...defaults[kind],...old};editor={kind,id};let fields='';if(kind==='customer')fields=input('name','Customer name',x.name,'text','required')+input('phone','Mobile / login number',x.phone,'tel','required')+input('address','Address',x.address)+input('registered','Registration date',x.registered,'date')+input('cowRate','Cow milk rate per litre',x.cowRate,'number','step="0.01" min="0"')+input('buffaloRate','Buffalo milk rate per litre',x.buffaloRate,'number','step="0.01" min="0"')+input('yogurtRate','Yogurt rate per kg',x.yogurtRate,'number','step="0.01" min="0"')+input('cowQty','Default cow milk litres/day',x.cowQty,'number','step="0.01" min="0"')+input('buffaloQty','Default buffalo milk litres/day',x.buffaloQty,'number','step="0.01" min="0"')+input('yogurtQty','Default yogurt kg/day',x.yogurtQty,'number','step="0.01" min="0"')+input('username','Unique customer username',x.username||'','text','required')+input('loginPassword',old?'Change login password (leave blank to keep)':'Customer password (min 6 characters)','','password',old?'minlength="6"':'required minlength="6"')+select('active','Customer status',[['true','Active'],['false','Inactive']],String(activeParty(x)));
if(kind==='supplier')fields=input('name','Supplier name',x.name,'text','required')+input('phone','Phone',x.phone,'tel')+input('address','Address',x.address)+input('registered','Registered',x.registered,'date')+input('cowRate','Cow milk purchase rate',x.cowRate,'number','step="0.01" min="0"')+input('buffaloRate','Buffalo milk purchase rate',x.buffaloRate,'number','step="0.01" min="0"')+select('paymentCycle','Usual supplier payment cycle',[['7','Weekly (7 days)'],['10','Every 10 days'],['14','Every 14 days'],['15','Every 15 days'],['30','Monthly'],['0','Flexible / manual']],String(x.paymentCycle??7))+select('active','Supplier status',[['true','Active'],['false','Inactive']],String(activeParty(x)));
if(kind==='staff')fields=input('name','Name',x.name,'text','required')+input('phone','Phone',x.phone,'tel')+input('role','Job title',x.role)+input('salary','Monthly salary',x.salary,'number','step="0.01" min="0"')+input('registered','Start date',x.registered,'date')+select('active','Status',[['true','Active'],['false','Inactive']],String(x.active));
if(kind==='expense')fields=input('date','Date',x.date,'date','required')+input('category','Category',x.category,'text','required')+input('description','Description',x.description)+input('amount','Amount (Rs)',x.amount,'number','step="0.01" min="0" required');
layout(`${title((id?'Edit ':'Add ')+kind)}<div class="panel"><form data-form="entity" class="formgrid">${fields}<div class="actions field full"><button class="btn" type="submit">Save ${kind}</button>${button('Cancel','cancel')}</div></form></div>`)}
function entityPage(kind){let label={customers:'Customers',suppliers:'Suppliers',staff:'Staff',expenses:'Expenses'}[kind],singular={customers:'customer',suppliers:'supplier',staff:'staff',expenses:'expense'}[kind],rows=list(kind).slice().sort((a,b)=>(b.registered||b.date||'').localeCompare(a.registered||a.date||''));let headers=kind==='customers'?['Customer','Phone','Rates (cow/buffalo/yogurt)','Daily quantities','Balance','Actions']:kind==='suppliers'?['Supplier','Phone','Milk rates','Owed','Actions']:kind==='staff'?['Name','Role','Monthly salary','Status','Actions']:['Date','Category','Description','Amount','Actions'];let rowsHtml=x=>{let cells=kind==='customers'?`<td><b>${esc(x.name)}</b><small>${esc(x.address)}</small><small class="${activeParty(x)?'':'inactive'}">${activeParty(x)?'Active':'Inactive'}</small></td><td>${esc(x.phone)}</td><td>${money(x.cowRate)} / ${money(x.buffaloRate)} / ${money(x.yogurtRate)}</td><td>${n(x.cowQty)} / ${n(x.buffaloQty)} / ${n(x.yogurtQty)}</td><td>${money(customerBalance(x.id))}</td>`:kind==='suppliers'?`<td><b>${esc(x.name)}</b><small>${esc(x.address)}</small><small class="${activeParty(x)?'':'inactive'}">${activeParty(x)?'Active':'Inactive'}</small></td><td>${esc(x.phone)}</td><td>${money(x.cowRate)} / ${money(x.buffaloRate)}</td><td>${money(supplierBalance(x.id))}</td>`:kind==='staff'?`<td>${esc(x.name)}<small>${esc(x.phone)}</small></td><td>${esc(x.role)}</td><td>${money(x.salary)}</td><td>${x.active!==false?'Active':'Inactive'}</td>`:`<td>${esc(x.date)}</td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td>${money(x.amount)}</td>`;return `<tr>${cells}<td>${['supplier','customer'].includes(singular)?iconAction('🧾','Generate invoice','invoice-party',singular+':'+x.id):''}${editActions(singular,x.id)}</td></tr>`};layout(`${title(label,rows.length+' records',action('+ Add '+singular,'add-'+singular))}<div class="panel">${paginate(kind,rows,headers,rowsHtml)}</div>`)}
function entryForm(id,type){let old=id?find('entries',id):null,e={date:today(),type:type||'delivery',partyId:'',cowQty:0,buffaloQty:0,yogurtQty:0,shopAmount:0,...old};editor={kind:'entry',id};let parties=e.type==='purchase'?list('suppliers'):e.type==='delivery'?list('customers'):[];if(!old)parties=parties.filter(activeParty);if(e.type==='shop'){layout(`${title(id?'Edit shop sale':'Shop sale','Enter the amount received in PKR')}<div class="panel"><form data-form="entry" class="formgrid"><input type="hidden" name="type" value="shop">${input('date','Date',dateOnly(e.date),'date','required')}${input('shopAmount','Sale amount (PKR)',e.shopAmount||amt(e),'number','step="0.01" min="0.01" required')}<div class="actions field full"><button class="btn" type="submit">Save shop sale</button>${button('Cancel','cancel')}</div></form></div>`);return}
 let existing=e.partyId?find(e.type==='purchase'?'suppliers':'customers',e.partyId):null;let fields=input('date','Date',dateOnly(e.date),'date','required')+`<input type="hidden" name="type" value="${e.type}">`+select('partyId',e.type==='purchase'?'Supplier':'Customer',[['','Choose account'],...parties.map(p=>[p.id,p.name])],e.partyId)+input('cowQty','Cow milk (L)',e.cowQty,'number','step="0.01" min="0"')+input('buffaloQty','Buffalo milk (L)',e.buffaloQty,'number','step="0.01" min="0"')+(e.type==='delivery'?input('yogurtQty','Yogurt (kg)',e.yogurtQty,'number','step="0.01" min="0"'):'');layout(`${title(id?'Edit entry':e.type==='delivery'?'Home delivery':'Supplier purchase','Default quantities and rates are filled automatically')}<div class="panel"><form data-form="entry" class="formgrid">${fields}<p class="field full note">Account rates are applied automatically. Previous transactions retain their historical rates.</p><div class="field full"><b>Calculated amount: <span id="entrytotal">${money(amt(e))}</span></b></div><div class="actions field full"><button class="btn" type="submit">Save entry</button>${button('Cancel','cancel')}</div></form></div>`);updateEntryTotal()}
function updateEntryTotal(){let f=$('[data-form="entry"]');if(!f)return;let v=formObj(f),p=find(v.type==='purchase'?'suppliers':'customers',v.partyId);if(v.type==='shop')return;v.cowRate=n(p?.cowRate);v.buffaloRate=n(p?.buffaloRate);v.yogurtRate=v.type==='delivery'?n(p?.yogurtRate):0;let el=$('#entrytotal');if(el)el.textContent=money(amt(v))}
function fillCustomerQuantities(){let f=$('[data-form="entry"]');if(!f||f.elements.type.value!=='delivery')return;let c=find('customers',f.elements.partyId.value);if(!c)return;let date=f.elements.date.value;let e=list('entries').find(e=>e.type==='delivery'&&e.partyId===c.id&&e.date===date);for(let k of ['cowQty','buffaloQty','yogurtQty'])f.elements[k].value=n(e?e[k]:c[k]);updateEntryTotal()}

let entryDateFilter=today();
function entriesPage(){
 const kinds=[['delivery','🏠 Home Delivery','Enter customer milk and yogurt'],['purchase','🚚 Supplier Purchase','Record milk purchased'],['shop','🏪 Shop Sale','Enter rupees only']];
 layout(`${title('Daily entries','Fast entry and history — one category at a time',action('⚡ Bulk entries','bulk'))}<div class="entry-tabs" role="tablist" aria-label="Entry category">${kinds.map(([type,label])=>`<button type="button" class="entry-tab ${entryTab===type?'active':''}" role="tab" aria-selected="${entryTab===type}" data-action="entry-tab" data-id="${type}">${label}</button>`).join('')}</div><div class="panel entry-current"><div class="section-title"><div><h3>${kinds.find(k=>k[0]===entryTab)[1]}</h3><p class="muted">${kinds.find(k=>k[0]===entryTab)[2]}</p></div>${action('＋ New entry', 'quick-'+entryTab)}</div><div class="toolrow"><label>Date <input id="entryfilter" type="date" value="${esc(entryDateFilter)}"></label>${action('All dates','clear-filter')}</div><div id="entrytable"></div></div>`);
 renderEntryTables();
}
function renderEntryTables(){
 let date=$('#entryfilter')?.value??entryDateFilter;entryDateFilter=date;
 const rows=list('entries').filter(e=>e.type===entryTab&&(!date||dateOnly(e.date)===date)).slice().sort((a,b)=>dateOnly(b.date).localeCompare(dateOnly(a.date)));
 let headers,renderRow;
 if(entryTab==='delivery'){
  headers=['Date','Customer','Cow L','Buffalo L','Yogurt kg','Amount','Actions'];
  renderRow=e=>`<tr><td>${esc(dateOnly(e.date))}</td><td>${esc(find('customers',e.partyId)?.name||'Deleted account')}</td><td>${n(e.cowQty)}</td><td>${n(e.buffaloQty)}</td><td>${n(e.yogurtQty)}</td><td>${money(amt(e))}</td><td>${editActions('entry',e.id)}</td></tr>`;
 }else if(entryTab==='purchase'){
  headers=['Date','Supplier','Cow L','Buffalo L','Amount','Actions'];
  renderRow=e=>`<tr><td>${esc(dateOnly(e.date))}</td><td>${esc(find('suppliers',e.partyId)?.name||'Deleted account')}</td><td>${n(e.cowQty)}</td><td>${n(e.buffaloQty)}</td><td>${money(amt(e))}</td><td>${editActions('entry',e.id)}</td></tr>`;
 }else{
  headers=['Date','Shop sale (PKR)','Actions'];
  renderRow=e=>`<tr><td>${esc(dateOnly(e.date))}</td><td><b>${money(amt(e))}</b></td><td>${editActions('entry',e.id)}</td></tr>`;
 }
 const el=$('#entrytable');if(el)el.innerHTML=paginate('entry-'+entryTab,rows,headers,renderRow);
}

function bulkPage(){editor={kind:'bulk'};layout(`${title('⚡ Bulk deliveries','All customers ready with their usual daily quantities')}<div class="panel"><form data-form="bulk"><div class="toolrow">${input('date','Delivery date',today(),'date','required')}${select('type','Record type',[['delivery','Home deliveries'],['purchase','Supplier purchases']],'delivery')}</div><div class="toolrow"><label class="checkbox-row"><input type="checkbox" id="bulkselectall" checked> Select all</label><span class="muted" id="bulkcount"></span></div><div id="bulkrows"></div><div class="actions bulk-save"><button class="btn" type="submit">Save selected entries</button>${button('Cancel','cancel')}</div><p class="note">Entries for the same account on this date are updated instead of duplicated. Unselected accounts are unchanged. Zero quantities on a selected account remove that day's existing entry.</p></form></div>`);renderBulk()}
function renderBulk(){let type=$('[data-form="bulk"] [name="type"]').value,parties=list(type==='delivery'?'customers':'suppliers').filter(activeParty),date=$('[data-form="bulk"] [name="date"]').value;$('#bulkrows').innerHTML=parties.length?`<div class="bulk-list">${parties.map(p=>{let existing=list('entries').find(e=>e.type===type&&e.partyId===p.id&&e.date===date);return `<div class="bulk-row" data-party="${p.id}"><label class="bulk-name"><input type="checkbox" name="selected" checked><span><b>${esc(p.name)}</b><small>${existing?'Already entered • updating':'Ready to save'}</small></span></label><div class="bulk-inputs"><label>Cow L<input type="number" min="0" step="0.01" name="cowQty" value="${existing?n(existing.cowQty):type==='delivery'?n(p.cowQty):0}"></label><label>Buffalo L<input type="number" min="0" step="0.01" name="buffaloQty" value="${existing?n(existing.buffaloQty):type==='delivery'?n(p.buffaloQty):0}"></label><label>Yogurt kg<input type="number" min="0" step="0.01" name="yogurtQty" value="${existing?n(existing.yogurtQty):type==='delivery'?n(p.yogurtQty):0}" ${type==='purchase'?'disabled':''}></label></div></div>`}).join('')}</div>`:'<div class="empty">Create customers or suppliers first.</div>';refreshBulkCount()}
function refreshBulkCount(){let c=$$('#bulkrows input[name="selected"]');let el=$('#bulkcount');if(el)el.textContent=`${c.filter(x=>x.checked).length} of ${c.length} selected`}
const $$=sel=>Array.from(document.querySelectorAll(sel));

function paymentForm(id){let p=id?find('payments',id):{date:today(),partyType:paymentTab,partyId:'',amount:0,note:''};editor={kind:'payment',id};layout(`${title(id?'Edit payment':'Record payment','Customer payments received or supplier payments paid')}<div class="panel"><form data-form="payment" class="formgrid">${input('date','Payment date',p.date,'date','required')}${select('partyType','Account type',[['customer','Customer (money received)'],['supplier','Supplier (money paid)']],p.partyType)}<label class="field" id="paymentparty">Account<select name="partyId"></select></label>${input('amount','Amount (Rs)',p.amount,'number','step="0.01" min="0.01" required')}${area('note','Reference / notes',p.note)}<div class="actions field full"><button class="btn" type="submit">Save payment</button>${button('Cancel','cancel')}</div></form></div>`);renderPaymentParties(p.partyId)}
