function bytesToBase64(bytes){let a=[];for(let i=0;i<bytes.length;i+=16384)a.push(String.fromCharCode(...bytes.subarray(i,i+16384)));return btoa(a.join(''))}
async function saveBinary(name,base64,mime){
 if(window.Capacitor?.isNativePlatform?.()){
  const fs=window.Capacitor.Plugins.Filesystem,share=window.Capacitor.Plugins.Share;
  if(!fs||!share)throw Error('Native Filesystem and Share plugins are required');
  const file=await fs.writeFile({path:name,directory:'CACHE',data:base64});
  await share.share({title:'Punjab Dairy '+name,url:file.uri,dialogTitle:'Save or send '+name});
 }else{
  const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));
  const url=URL.createObjectURL(new Blob([bytes],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)
 }
}
async function exportInvoice(format){
 if(!activeInvoice)return alert('Generate a bill first');
 try{
  const canvas=await invoiceCanvas(activeInvoice),name='Punjab-Dairy-'+activeInvoice.type+'-'+activeInvoice.from+'-'+activeInvoice.to;
  if(format==='pdf')await saveBinary(name+'.pdf',bytesToBase64(jpegPDF(canvas)),'application/pdf');
  else await saveBinary(name+'.png',pngBytes(canvas),'image/png');
 }catch(e){alert('Invoice export failed: '+(e.message||String(e)))}
}

async function download(name,content,mime){
 // Capacitor's Filesystem + Android Sharesheet works reliably in native WebViews.
 const native=window.Capacitor?.isNativePlatform?.();
 if(native){
   try{
     const fs=window.Capacitor.Plugins.Filesystem, share=window.Capacitor.Plugins.Share;
     if(!fs||!share)throw Error('Native file export plugins missing. Rebuild and install the new APK.');
     const result=await fs.writeFile({path:name,data:content,directory:'CACHE',encoding:'utf8'});
     await share.share({title:'Punjab Dairy backup',text:'Save '+name+' to a safe place',url:result.uri,dialogTitle:'Save or share '+name});
     return;
   }catch(err){alert('Export could not be completed: '+(err.message||err)+'\nTry Files or Google Drive in the share menu.');return}
 }
 const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
const csv=v=>{let value=String(v??'');if(/^[=+@-]/.test(value))value="'"+value;return '"'+value.replaceAll('"','""')+'"'};
function exportCSV(rows,name){return download(name,'\ufeff'+rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function doAction(key,id){if(key==='logout'){session=null;localStorage.removeItem('pd-session-id');view='login';return auth()}if(key==='cancel'){editor=null;return render()}if(key==='bulk')return bulkPage();if(key==='go-back'){if(editor){editor=null;return render()}if(navHistory.length){view=navHistory.pop();return render()}view='dashboard';return render()}if(key==='profit-point'){const a=monthAccounting(selectedProfitMonth),v=a.points.find(x=>x.date===id);const el=$('#profitdetail');if(el&&v)el.textContent=id+'  •  Gross profit: '+money(v.gross);return}if(key==='entry-tab'){entryTab=['delivery','purchase','shop'].includes(id)?id:'delivery';return entriesPage()}if(key==='payment-tab'){paymentTab=id==='supplier'?'supplier':'customer';return paymentsPage()}if(key==='create-admin')return adminForm();if(key==='change-password')return passwordForm();if(key==='go-suppliers'){navHistory.push(view);view='suppliers';return render()}if(key==='go-customers'){navHistory.push(view);view='customers';return render()}if(key==='invoice-party'){navHistory.push(view);view='invoices';render();const sel=$('#invoiceParty');if(sel){sel.value=id;generateInvoice()}return}if(key==='page-prev'||key==='page-next')return setPage(id,key==='page-prev'?-1:1);if(key==='go-remainder'){navHistory.push(view);view='remainder';return render()}if(key==='delete-remainder'){if(!confirm('Delete this remaining stock record?'))return;data.remainders=list('remainders').filter(x=>x.id!==id);await saveDB();return render()}if(key.startsWith('quick-')){if(key!=='quick-expense')entryTab=['shop','purchase','delivery'].includes(key.slice(6))?key.slice(6):'delivery';return key==='quick-expense'?entityForm('expense'):entryForm(null,entryTab)}if(key==='add-entry')return entryForm();if(key==='edit-entry')return entryForm(id);if(key==='add-payment')return paymentForm();if(key==='edit-payment')return paymentForm(id);for(let kind of ['customer','supplier','staff','expense']){if(key==='add-'+kind)return entityForm(kind);if(key==='edit-'+kind)return entityForm(kind,id)}if(key.startsWith('delete-')){let kind=key.slice(7),plural={customer:'customers',supplier:'suppliers',staff:'staff',expense:'expenses',entry:'entries',payment:'payments'}[kind];if(!plural)return;let used=kind==='customer'||kind==='supplier'?list('entries').some(e=>e.partyId===id)||list('payments').some(p=>p.partyId===id):false;if(used)return alert('This account has transactions or payments and cannot be deleted. Keep it for accurate balances.');if(!confirm('Delete this record permanently?'))return;data[plural]=data[plural].filter(x=>x.id!==id);if(kind==='customer')data.users=data.users.filter(x=>x.customerId!==id);await saveDB();flash='Record deleted';return render()}if(key==='clear-filter'){$('#entryfilter').value='';pageState['entry-'+entryTab]=1;return renderEntryTables()}if(key==='generate-invoice')return generateInvoice();if(key==='print-invoice'&&activeInvoice)return exportInvoice('pdf');if(key==='share-invoice'&&activeInvoice)return exportInvoice('png');if(key==='invoice-csv'&&activeInvoice){let x=activeInvoice;return exportCSV([['Date','Type','Cow L','Buffalo L','Yogurt kg','Amount'],...x.entries.map(e=>[e.date,e.type,e.cowQty,e.buffaloQty,e.yogurtQty,amt(e)]),...x.payments.map(p=>[p.date,'Payment','','','',-n(p.amount)]),['','','','','Closing balance',x.balance]],'punjab-dairy-statement.csv')}if(key==='export-json'){await saveDB();return download('punjab-dairy-backup-'+today()+'.json',JSON.stringify(data,null,2),'application/json')}if(key==='export-csv')return exportCSV([['Date','Type','Account','Cow litres','Buffalo litres','Yogurt kg','Cow rate','Buffalo rate','Yogurt rate','Amount'],...data.entries.map(e=>[e.date,e.type,find(e.type==='purchase'?'suppliers':'customers',e.partyId)?.name||'Walk-in',e.cowQty,e.buffaloQty,e.yogurtQty,e.cowRate,e.buffaloRate,e.yogurtRate,amt(e)])],'punjab-dairy-transactions-'+today()+'.csv');if(key==='import-json'){let file=$('#importfile').files[0];if(!file)return alert('Select a JSON file');let obj;try{obj=JSON.parse(await file.text());if(!obj||!Array.isArray(obj.users)||!Array.isArray(obj.entries)||!Array.isArray(obj.customers)||!Array.isArray(obj.suppliers)||!Array.isArray(obj.payments)||!Array.isArray(obj.expenses)||!Array.isArray(obj.staff)||!Array.isArray(obj.feedback)||obj.version!==1)throw Error('Invalid backup');}catch(e){return alert('Invalid Punjab Dairy backup: '+e.message)}if(!confirm('Replace ALL existing local data with this backup? This cannot be undone.'))return;data={...blank(),...obj,remainders:Array.isArray(obj.remainders)?obj.remainders:[]};await saveDB();localStorage.removeItem('pd-session-id');Object.keys(pageState).forEach(k=>delete pageState[k]);session=null;view='login';flash='Backup imported. Please log in.';return auth()}}
document.addEventListener('submit',e=>{let f=e.target.closest('form[data-form]');if(f){e.preventDefault();submit(f)}});document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b){e.preventDefault();doAction(b.dataset.action,b.dataset.id)}let v=e.target.closest('[data-view]');if(v){if(view!==v.dataset.view)navHistory.push(view);view=v.dataset.view;editor=null;render()}});document.addEventListener('change',change);document.addEventListener('input',e=>{if(e.target.closest('[data-form="entry"]'))change(e)});
(async()=>{try{db=await openDB();data=await readDB()||blank();if(!data.users) data=blank();data.remainders ||= [];if(!data.users.length){let u=await credentials('','dairy1','admin');u.username='punjab';data.users.push(u);await saveDB()}let remembered=localStorage.getItem('pd-session-id');let user=data.users.find(x=>x.id===remembered);if(user)session={role:user.role,id:user.id,customerId:user.customerId};view=session?'dashboard':'login';render();if(!window.Capacitor?.isNativePlatform?.()&&'serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}catch(e){app.innerHTML=`<div class="auth"><div class="auth-card"><h2>Cannot access local data</h2><p>${esc(e.message)}</p><p>Use a modern browser with IndexedDB enabled. Private/incognito mode may block storage.</p></div></div>`}})();
